use crate::geometry_error::GeometryError;
use glam::DVec2;

/// Represents a point on a planar contour with position and tangent information.
///
/// Points are typically generated by sampling curves (arcs, NURBS, etc.).
#[derive(Debug, Clone, PartialEq)]
pub struct Point {
    /// The 2D position of the point.
    pub position: DVec2,
    /// The tangent vector at this point.
    pub tangent: DVec2,
}

impl Point {
    /// Creates a new point with the specified position and tangent.
    ///
    /// # Arguments
    /// * `position` - The 2D position of the point
    /// * `tangent` - The tangent vector at this point
    pub fn new(position: DVec2, tangent: DVec2) -> Self {
        Self { position, tangent }
    }
}

/// Represents a segment of a contour defined by start and end points.
///
/// A segment connects two points and has an identifier that can be used
/// to group related segments together.
#[derive(Debug, Clone, PartialEq)]
pub struct Segment {
    /// The starting point of the segment.
    pub start: Point,
    /// The ending point of the segment.
    pub end: Point,
    /// The segment identifier.
    pub segment: u32,
}

impl Segment {
    /// Creates a new segment with the specified start, end, and segment identifier.
    ///
    /// # Arguments
    /// * `start` - The starting point of the segment
    /// * `end` - The ending point of the segment
    /// * `segment` - The segment identifier
    pub fn new(start: Point, end: Point, segment: u32) -> Self {
        Self {
            start,
            end,
            segment,
        }
    }
}

/// Represents a contour composed of multiple segments.
///
/// A contour is a sequence of segments that form a connected curve.
/// It can be either open or closed.
#[derive(Debug, Clone, PartialEq)]
pub struct Contour {
    /// The sequence of segments that make up this contour.
    pub segments: Vec<Segment>,
    /// Whether this contour is closed (forms a loop) or open.
    pub closed: bool,
}

impl Contour {
    /// Creates a new empty contour.
    pub fn new() -> Self {
        Self {
            segments: Vec::new(),
            closed: false,
        }
    }

    /// Creates a new contour with the given segments.
    ///
    /// # Arguments
    /// * `segments` - The sequence of segments for this contour
    pub fn with_segments(segments: Vec<Segment>) -> Self {
        Self {
            segments,
            closed: false,
        }
    }

    /// Creates a new closed contour with the given segments.
    ///
    /// # Arguments
    /// * `segments` - The sequence of segments for this contour
    pub fn with_segments_closed(segments: Vec<Segment>) -> Self {
        Self {
            segments,
            closed: true,
        }
    }

    /// Creates a new contour with the given segments and closed state.
    ///
    /// # Arguments
    /// * `segments` - The sequence of segments for this contour
    /// * `closed` - Whether the contour is closed
    pub fn with_segments_and_closed(segments: Vec<Segment>, closed: bool) -> Self {
        Self { segments, closed }
    }

    /// Adds a segment to the contour.
    ///
    /// # Arguments
    /// * `segment` - The segment to add
    pub fn add_segment(&mut self, segment: Segment) {
        self.segments.push(segment);
    }

    /// Returns the number of segments in the contour.
    pub fn len(&self) -> usize {
        self.segments.len()
    }

    /// Returns true if the contour contains no segments.
    pub fn is_empty(&self) -> bool {
        self.segments.is_empty()
    }

    /// Returns true if the contour is closed.
    pub fn is_closed(&self) -> bool {
        self.closed
    }

    /// Sets whether the contour is closed.
    ///
    /// # Arguments
    /// * `closed` - Whether the contour should be closed
    pub fn set_closed(&mut self, closed: bool) {
        self.closed = closed;
    }

    /// Closes the contour (sets closed to true).
    pub fn close(&mut self) {
        self.closed = true;
    }

    /// Opens the contour (sets closed to false).
    pub fn open(&mut self) {
        self.closed = false;
    }
}

impl Default for Contour {
    fn default() -> Self {
        Self::new()
    }
}

/// Represents a collection of contours.
///
/// This structure holds multiple contours that together define an outline,
/// which may include outer boundaries and inner holes.
#[derive(Debug, Clone, PartialEq)]
pub struct ContourSet {
    /// The collection of contours.
    pub contours: Vec<Contour>,
}

impl ContourSet {
    /// Creates a new empty contour set.
    pub fn new() -> Self {
        Self {
            contours: Vec::new(),
        }
    }

    /// Creates a new contour set with the given contours.
    ///
    /// # Arguments
    /// * `contours` - The collection of contours
    pub fn with_contours(contours: Vec<Contour>) -> Self {
        Self { contours }
    }

    /// Adds a contour to the set.
    ///
    /// # Arguments
    /// * `contour` - The contour to add
    pub fn add_contour(&mut self, contour: Contour) {
        self.contours.push(contour);
    }

    /// Returns the number of contours.
    pub fn len(&self) -> usize {
        self.contours.len()
    }

    /// Returns true if there are no contours.
    pub fn is_empty(&self) -> bool {
        self.contours.is_empty()
    }
}

impl Default for ContourSet {
    fn default() -> Self {
        Self::new()
    }
}

/// A trait for objects that can sample their contour into discrete segments.
///
/// This trait provides a common interface for generating sampled contours
/// from various geometric shapes or profiles.
pub trait SampleContour {
    /// Samples the contour of the object into discrete segments.
    ///
    /// # Arguments
    /// * `sample_distance` - The maximum distance between consecutive sample points
    ///
    /// # Returns
    /// A `Result` containing the `ContourSet` representation,
    /// or a `GeometryError` if the sampling fails.
    fn sample_contour(&self, sample_distance: f64) -> Result<ContourSet, GeometryError>;
}

#[cfg(test)]
mod tests {
    use super::*;

    // Point tests

    #[test]
    fn test_point_creation() {
        let position = DVec2::new(1.0, 2.0);
        let tangent = DVec2::new(1.0, 0.0);

        let point = Point::new(position, tangent);

        assert_eq!(point.position, position);
        assert_eq!(point.tangent, tangent);
    }

    #[test]
    fn test_point_clone() {
        let point1 = Point::new(DVec2::new(1.0, 2.0), DVec2::new(1.0, 0.0));
        let point2 = point1.clone();

        assert_eq!(point1, point2);
    }

    #[test]
    fn test_point_equality() {
        let point1 = Point::new(DVec2::new(1.0, 2.0), DVec2::new(1.0, 0.0));
        let point2 = Point::new(DVec2::new(1.0, 2.0), DVec2::new(1.0, 0.0));
        let point3 = Point::new(DVec2::new(1.0, 2.0), DVec2::new(0.0, 1.0));

        assert_eq!(point1, point2);
        assert_ne!(point1, point3);
    }

    // Segment tests

    #[test]
    fn test_segment_creation() {
        let start = Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0));
        let end = Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0));
        let segment_id = 5;

        let segment = Segment::new(start.clone(), end.clone(), segment_id);

        assert_eq!(segment.start, start);
        assert_eq!(segment.end, end);
        assert_eq!(segment.segment, segment_id);
    }

    #[test]
    fn test_segment_clone() {
        let start = Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0));
        let end = Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0));
        let segment1 = Segment::new(start, end, 1);
        let segment2 = segment1.clone();

        assert_eq!(segment1, segment2);
    }

    #[test]
    fn test_segment_equality() {
        let start = Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0));
        let end = Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0));

        let segment1 = Segment::new(start.clone(), end.clone(), 1);
        let segment2 = Segment::new(start.clone(), end.clone(), 1);
        let segment3 = Segment::new(start.clone(), end.clone(), 2);

        assert_eq!(segment1, segment2);
        assert_ne!(segment1, segment3);
    }

    // Contour tests

    #[test]
    fn test_contour_new() {
        let contour = Contour::new();
        assert!(contour.is_empty());
        assert_eq!(contour.len(), 0);
    }

    #[test]
    fn test_contour_add_segment() {
        let mut contour = Contour::new();
        let segment1 = Segment::new(
            Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
            Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
            0,
        );
        let segment2 = Segment::new(
            Point::new(DVec2::new(1.0, 0.0), DVec2::new(0.0, 1.0)),
            Point::new(DVec2::new(1.0, 1.0), DVec2::new(0.0, 1.0)),
            1,
        );

        contour.add_segment(segment1);
        contour.add_segment(segment2);

        assert_eq!(contour.len(), 2);
        assert!(!contour.is_empty());
    }

    #[test]
    fn test_contour_with_segments() {
        let segments = vec![
            Segment::new(
                Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
                Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
                0,
            ),
            Segment::new(
                Point::new(DVec2::new(1.0, 0.0), DVec2::new(0.0, 1.0)),
                Point::new(DVec2::new(1.0, 1.0), DVec2::new(0.0, 1.0)),
                1,
            ),
            Segment::new(
                Point::new(DVec2::new(1.0, 1.0), DVec2::new(-1.0, 0.0)),
                Point::new(DVec2::new(0.0, 1.0), DVec2::new(-1.0, 0.0)),
                2,
            ),
        ];

        let contour = Contour::with_segments(segments.clone());

        assert_eq!(contour.len(), 3);
        assert!(!contour.is_closed()); // Default is open
        assert_eq!(contour.segments, segments);
    }

    #[test]
    fn test_contour_same_segment_id() {
        let mut contour = Contour::new();

        // Multiple segments with the same segment ID (e.g., sampled from an arc)
        for i in 0..4 {
            let t1 = i as f64 * 0.25;
            let t2 = (i + 1) as f64 * 0.25;
            let segment = Segment::new(
                Point::new(DVec2::new(t1, t1 * t1), DVec2::new(1.0, 2.0 * t1)),
                Point::new(DVec2::new(t2, t2 * t2), DVec2::new(1.0, 2.0 * t2)),
                0, // All from segment 0
            );
            contour.add_segment(segment);
        }

        assert_eq!(contour.len(), 4);
        assert!(contour.segments.iter().all(|s| s.segment == 0));
    }

    #[test]
    fn test_contour_default() {
        let contour = Contour::default();
        assert!(contour.is_empty());
        assert!(!contour.is_closed());
    }

    #[test]
    fn test_contour_closed_state() {
        let mut contour = Contour::new();
        assert!(!contour.is_closed());

        contour.close();
        assert!(contour.is_closed());

        contour.open();
        assert!(!contour.is_closed());

        contour.set_closed(true);
        assert!(contour.is_closed());

        contour.set_closed(false);
        assert!(!contour.is_closed());
    }

    #[test]
    fn test_contour_with_segments_closed() {
        let segments = vec![Segment::new(
            Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
            Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
            0,
        )];

        let contour = Contour::with_segments_closed(segments.clone());
        assert_eq!(contour.len(), 1);
        assert!(contour.is_closed());
        assert_eq!(contour.segments, segments);
    }

    #[test]
    fn test_contour_with_segments_and_closed() {
        let segments = vec![Segment::new(
            Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
            Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
            0,
        )];

        let contour_open = Contour::with_segments_and_closed(segments.clone(), false);
        assert!(!contour_open.is_closed());
        assert_eq!(contour_open.segments, segments);

        let contour_closed = Contour::with_segments_and_closed(segments.clone(), true);
        assert!(contour_closed.is_closed());
        assert_eq!(contour_closed.segments, segments);
    }

    #[test]
    fn test_contour_closed_equality() {
        let segments = vec![Segment::new(
            Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
            Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
            0,
        )];

        let contour1 = Contour::with_segments_and_closed(segments.clone(), true);
        let contour2 = Contour::with_segments_and_closed(segments.clone(), true);
        let contour3 = Contour::with_segments_and_closed(segments.clone(), false);

        assert_eq!(contour1, contour2);
        assert_ne!(contour1, contour3); // Different closed state
    }

    // ContourSet tests

    #[test]
    fn test_contour_set_new() {
        let contour_set = ContourSet::new();
        assert!(contour_set.is_empty());
        assert_eq!(contour_set.len(), 0);
    }

    #[test]
    fn test_contour_set_add_contour() {
        let mut contour_set = ContourSet::new();
        let contour1 = Contour::with_segments(vec![Segment::new(
            Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
            Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
            0,
        )]);
        let contour2 = Contour::with_segments(vec![Segment::new(
            Point::new(DVec2::new(2.0, 2.0), DVec2::new(1.0, 0.0)),
            Point::new(DVec2::new(3.0, 2.0), DVec2::new(1.0, 0.0)),
            1,
        )]);

        contour_set.add_contour(contour1);
        contour_set.add_contour(contour2);

        assert_eq!(contour_set.len(), 2);
        assert!(!contour_set.is_empty());
    }

    #[test]
    fn test_contour_set_with_contours() {
        let contours = vec![
            Contour::with_segments(vec![Segment::new(
                Point::new(DVec2::new(0.0, 0.0), DVec2::new(1.0, 0.0)),
                Point::new(DVec2::new(1.0, 0.0), DVec2::new(1.0, 0.0)),
                0,
            )]),
            Contour::with_segments(vec![Segment::new(
                Point::new(DVec2::new(1.0, 1.0), DVec2::new(0.0, 1.0)),
                Point::new(DVec2::new(1.0, 2.0), DVec2::new(0.0, 1.0)),
                1,
            )]),
        ];

        let contour_set = ContourSet::with_contours(contours.clone());

        assert_eq!(contour_set.len(), 2);
        assert_eq!(contour_set.contours, contours);
    }

    #[test]
    fn test_contour_set_default() {
        let contour_set = ContourSet::default();
        assert!(contour_set.is_empty());
    }

    // SampleContour trait tests

    /// A test implementation of SampleContour for a simple rectangular shape.
    struct TestRectangle {
        width: f64,
        height: f64,
    }

    impl SampleContour for TestRectangle {
        fn sample_contour(&self, sample_distance: f64) -> Result<ContourSet, GeometryError> {
            if sample_distance <= 0.0 {
                return Err(GeometryError::InvalidParameter {
                    parameter: "sample_distance".to_string(),
                    message: "Sample distance must be positive".to_string(),
                });
            }

            let mut contour = Contour::new();

            // Bottom edge (segment 0)
            let bottom_samples = (self.width / sample_distance).ceil() as usize;
            for i in 0..bottom_samples {
                let t1 = (i as f64) / bottom_samples as f64;
                let t2 = ((i + 1) as f64) / bottom_samples as f64;
                let x1 = t1 * self.width;
                let x2 = t2 * self.width;
                contour.add_segment(Segment::new(
                    Point::new(DVec2::new(x1, 0.0), DVec2::new(1.0, 0.0)),
                    Point::new(DVec2::new(x2, 0.0), DVec2::new(1.0, 0.0)),
                    0,
                ));
            }

            // Right edge (segment 1)
            let right_samples = (self.height / sample_distance).ceil() as usize;
            for i in 0..right_samples {
                let t1 = (i as f64) / right_samples as f64;
                let t2 = ((i + 1) as f64) / right_samples as f64;
                let y1 = t1 * self.height;
                let y2 = t2 * self.height;
                contour.add_segment(Segment::new(
                    Point::new(DVec2::new(self.width, y1), DVec2::new(0.0, 1.0)),
                    Point::new(DVec2::new(self.width, y2), DVec2::new(0.0, 1.0)),
                    1,
                ));
            }

            // Top edge (segment 2)
            let top_samples = (self.width / sample_distance).ceil() as usize;
            for i in 0..top_samples {
                let t1 = (i as f64) / top_samples as f64;
                let t2 = ((i + 1) as f64) / top_samples as f64;
                let x1 = self.width - t1 * self.width;
                let x2 = self.width - t2 * self.width;
                contour.add_segment(Segment::new(
                    Point::new(DVec2::new(x1, self.height), DVec2::new(-1.0, 0.0)),
                    Point::new(DVec2::new(x2, self.height), DVec2::new(-1.0, 0.0)),
                    2,
                ));
            }

            // Left edge (segment 3)
            let left_samples = (self.height / sample_distance).ceil() as usize;
            for i in 0..left_samples {
                let t1 = (i as f64) / left_samples as f64;
                let t2 = ((i + 1) as f64) / left_samples as f64;
                let y1 = self.height - t1 * self.height;
                let y2 = self.height - t2 * self.height;
                contour.add_segment(Segment::new(
                    Point::new(DVec2::new(0.0, y1), DVec2::new(0.0, -1.0)),
                    Point::new(DVec2::new(0.0, y2), DVec2::new(0.0, -1.0)),
                    3,
                ));
            }

            let mut contour_set = ContourSet::new();
            contour_set.add_contour(contour);

            Ok(contour_set)
        }
    }

    #[test]
    fn test_sample_contour_trait_rectangle() {
        let rect = TestRectangle {
            width: 10.0,
            height: 5.0,
        };

        let result = rect.sample_contour(2.0);
        assert!(result.is_ok());

        let contour_set = result.unwrap();
        assert_eq!(contour_set.len(), 1);
        assert!(!contour_set.contours[0].is_empty());

        // Verify that we have segments from all 4 edges
        let contour = &contour_set.contours[0];
        let segment_ids: Vec<u32> = contour
            .segments
            .iter()
            .map(|s| s.segment)
            .collect::<std::collections::HashSet<_>>()
            .into_iter()
            .collect();
        assert_eq!(segment_ids.len(), 4); // 4 different segment IDs (0, 1, 2, 3)
    }

    #[test]
    fn test_sample_contour_trait_invalid_distance() {
        let rect = TestRectangle {
            width: 10.0,
            height: 5.0,
        };

        let result = rect.sample_contour(-1.0);
        assert!(result.is_err());

        let result = rect.sample_contour(0.0);
        assert!(result.is_err());
    }

    #[test]
    fn test_sample_contour_trait_fine_sampling() {
        let rect = TestRectangle {
            width: 2.0,
            height: 2.0,
        };

        let result = rect.sample_contour(0.5);
        assert!(result.is_ok());

        let contour_set = result.unwrap();
        let contour = &contour_set.contours[0];

        // With smaller sample distance, we should get more segments
        assert!(contour.len() >= 16); // At least 4 segments per edge * 4 edges
    }

    #[test]
    fn test_sample_contour_consecutive_same_segment_id() {
        let rect = TestRectangle {
            width: 4.0,
            height: 2.0,
        };

        let result = rect.sample_contour(1.0);
        assert!(result.is_ok());

        let contour_set = result.unwrap();
        let contour = &contour_set.contours[0];

        // Find consecutive segments with the same segment ID
        let mut has_consecutive_same_segment = false;
        for i in 0..contour.segments.len() - 1 {
            if contour.segments[i].segment == contour.segments[i + 1].segment {
                has_consecutive_same_segment = true;
                break;
            }
        }

        assert!(
            has_consecutive_same_segment,
            "Should have consecutive segments with the same segment ID"
        );
    }

    #[test]
    fn test_trait_object_sample_contour() {
        let rect: Box<dyn SampleContour> = Box::new(TestRectangle {
            width: 5.0,
            height: 5.0,
        });

        let result = rect.sample_contour(1.0);
        assert!(result.is_ok());
    }
}
